We say that a complex sequence $\alpha_n$ satisfies the \textbf{Siegel-Walfisz condition} if for every $d\ge 1$, $q\ge 1$ and $(a,q)=1$ and every $A>1$ we have
\begin{equation}
\Bigl|\sum_{\substack{n\sim N\\ n\equiv a\Mod{q}\\ (n,d)=1}}\alpha_n-\frac{1}{\phi(q)}\sum_{\substack{n\sim N\\ (n,d q)=1}}\alpha_n\Bigr|\ll_A \frac{N\tau(d)^{B_0}}{(\log{N})^A}.
\label{eq:SiegelWalfisz}
\end{equation}

\begin{equation}
\Bigl|\sum_{\substack{n\sim N\\ n\equiv a\Mod{q}\\ (n,d)=1}}\alpha_n-\frac{1}{\phi(q)}\sum_{\substack{n\sim N\\ (n,d q)=1}}\alpha_n\Bigr|\ll_A \frac{N\tau(d)^{B_0}}{(\log{N})^A}.
\label{eq:SiegelWalfisz}
\end{equation}

