&\ll  \sum_{\substack{f>z_0\\ f|e}}D Q R \frac{x \tau(f)^{O_{B_0}(1)}}{Q D R f}(\log{x})^{O_{B_0}(1)}\\
&\ll \frac{x(\log{x})^{O_{B_0(1)}}}{z_0^{1/2}}\sum_{f|e}\frac{\tau(f)^{O_{B_0}(1)}}{f^{1/2}}\\
&\ll \frac{x(\log{x})^{O_{B_0(1)}}}{z_0^{1/2}}\exp(O_{B_0}((\log{x})^{1/2})).
\end{align*}

\begin{align*}
&\ll \sum_{\substack{f>z_0\\ f|e}}\sum_{d\sim D}\sum_{q\sim Q}\sum_{\substack{r\sim R\\ f|r}}\sum_{m\sim M}\sum_{\substack{n\sim N}}\tau(q d r n m)^{2B_0}\Bigl(\mathbf{1}_{mn\equiv a\Mod{qdr}}+\frac{1}{\phi(qdr)}\Bigr)\\
&\ll x(\log{x})^{O_{B_0(1)}}\sum_{\substack{f>z_0\\ f|e}}\frac{\tau(f)^{O_{B_0}(1)}}{f}\\
&\ll \frac{x(\log{x})^{O_{B_0(1)}}}{z_0^{1/2}}\exp(O_{B_0}((\log{x})^{1/2}))
\end{align*}

\begin{align*}
\mathscr{S}&=\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_{\substack{q\sim Q\\ (q,a)=1}}\sum_{\substack{r\sim R\\ (r,a e)=1}}\lambda_{q,d,r}\gamma_{q,d}\sum_{\substack{m\sim M\\ (m,q d)=1}}\beta_m\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}\\ (b,q d e )=1}}\\
&\qquad \times\sum_{\substack{n\sim N\\ (n,e)=1}}\alpha_n\Bigl(\mathbf{1}_{\substack{m n\equiv a\Mod{q r d}\\ n\equiv b\Mod{q d e}}}-\frac{\mathbf{1}_{(m n,q r d)=1}}{\phi(q r d e)}\Bigr)\\
&\qquad+O_A\Bigl(\frac{x}{(\log{x})^A}\Bigr).
\end{align*}

\begin{align*}
\mathscr{S}&=\frac{1}{\mathscr{E}_0}\sum_{e\sim E}\mu^2(e)\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_{\substack{q\sim Q\\ (q,a)=1}}\sum_{\substack{r\sim R\\ (r,a e)=1}}\lambda_{q,d,r}\gamma_{q,d}\sum_{m\sim M}\beta_m\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}\\ (b,q d e)=1}}\\
&\qquad\times\sum_{\substack{n\sim N\\ (n,e)=1}}\alpha_n\Bigl(\mathbf{1}_{\substack{m n\equiv a\Mod{q r d}\\ n\equiv b\Mod{q d e}}}-\frac{\mathbf{1}_{(m n,q r d)=1}}{\phi(q r d e)}\Bigr)\\
&\qquad +O_A\Bigl(\frac{x}{(\log{x})^A}\Bigr),
\end{align*}

\begin{align*}
|\mathscr{S}|^2
&\le \frac{1}{\mathscr{E}_0^2}\Bigl(\sum_{e\sim E}\sum_{q\sim Q} \sum_{d\sim D}\sum_{\substack{m\sim M\\ (m,q d)=1}}\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}}}|\gamma_{q,d}|^2|\beta_m|^2\Bigr)  \mathscr{S}'+O_A\Bigl(\frac{x^2}{(\log{x})^{2A}}\Bigr)\\
&\ll M Q D(\log{x})^{O_{B_0}(1)} \mathscr{S}'+O_A\Bigl(\frac{x^2}{(\log{x})^{2A}}\Bigr),
\end{align*}

\begin{align*}
\mathscr{S}'&:=\sum_{e\sim E}\mu^2(e)\sum_{\substack{q\sim Q\\ (q,a)=1}}\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_{m\sim M}\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}\\ (b,q d e )=1}}\\
&\qquad\times\Bigl|\sum_{\substack{r\sim R\\ (r,a e)=1}}\lambda_{q,d,r}\sum_{\substack{n\sim N\\ (n,e)=1}}\alpha_n\Bigl(\mathbf{1}_{\substack{m n\equiv a\Mod{q d r}\\ n\equiv b\Mod{q d e}}}-\frac{\mathbf{1}_{(m n,qd r)=1}}{\phi(q d r e)}\Bigr)\Bigr|^2.
\end{align*}

\begin{align}
\mathscr{S}'&\le \sum_{\substack{q\\ (q,a)=1}}\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_m \psi_0\Bigl(\frac{q}{Q}\Bigr)\psi_0\Bigl(\frac{m}{M}\Bigr)\sum_{e\sim E}\mu^2(e)\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}\\ (b,q d e )=1}}\nonumber\\
&\qquad\times \Bigl|\sum_{\substack{r\sim R\\ (r,a e)=1}}\lambda_{q,d,r}\sum_{\substack{n\sim N\\ (n,e)=1}}\alpha_n\Bigl(\mathbf{1}_{\substack{m n\equiv a\Mod{q d r}\\ n\equiv b\Mod{q d e}}}-\frac{\mathbf{1}_{(m n,qd r)=1}}{\phi(q d r e)}\Bigr)\Bigr|^2\nonumber \\
&=  \mathscr{S}_{1}-2\Re(\mathscr{S}_{2})+\mathscr{S}_{3},\label{eq:S1Expansion}
\end{align}

\label{lmm:Simplification}
Let $N,M,Q,R \le x$ with $NM\asymp x$ and 
\begin{align}
Q R&<x^{2/3},\label{eq:CrudeSize}\\
Q R^2&< M x^{1-2\epsilon}.\label{eq:CrudeSize2}
\end{align}
Let $\lambda_{q,r}$ and $\alpha_n$ be complex sequences supported on $P^-(n),P^-(r)\ge z_0$ with $|\lambda_{q,r}|\le \tau(qr)^{B_0}$ and $|\alpha_n|\le \tau(n)^{B_0}$. Let $H:=\frac{Q R^2}{M}\log^5{x}$ and let
\begin{align*}
\mathscr{E}&:=\sum_{\substack{ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q r_2)=1}}\frac{\lambda_{q,r_1}\overline{\lambda_{q,r_2}}}{q r_1 r_2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q}\\ (n_1,n_2qr_1)=1\\(n_2,n_1qr_2)=1\\ |n_1-n_2|\ge N/(\log{x})^C}}\alpha_{n_1}\overline{\alpha_{n_2}}\\
&\qquad\qquad \times\sum_{1\le |h|\le H}\hat{\psi}_0\Bigl(\frac{h M}{q r_1 r_2}\Bigr)e\Bigl(\frac{ah\overline{n_1 r_2}}{q r_1}+\frac{ah\overline{n_2 q r_1}}{r_2}\Bigr).
\end{align*}
Then we have (uniformly in $C$)
\[
\mathscr{E}\ll_{B_0}\exp((\log\log{x})^5)\sup_{\substack{H'\le H\\ Q'\le 2Q\\ R_1,R_2\le 2R}}|\mathscr{E}'|+\frac{N^2}{Qx^\epsilon},
\]
where
\[
\mathscr{E}'=\sum_{\substack{Q\le q\le Q'\\ (q,a)=1}}\sum_{\substack{R\le r_1\le  R_1\\ R\le r_2\le R_2\\ (r_1a r_2)=1\\ (r_2,a q r_1)=1}}\frac{\lambda_{q,r_1}\overline{\lambda_{q,r_2}}}{q r_1 r_2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q}\\ (n_1,qr_1n_2)=1\\ (n_2,qr_2n_1)=1\\ (n_1r_2,n_2)\in\mathcal{N}\\ |n_1-n_2|\ge N/(\log{x})^C}}\alpha_{n_1}\overline{\alpha_{n_2}}\sum_{1\le |h| \le H'} e\Bigl(\frac{ ah\overline{n_2 q r_1}(n_1-n_2)}{n_1 r_2}\Bigr),
\]
and $\mathcal{N}$ is a set with the property that if $(a,b)\in\mathcal{N}$ and $(a',b')\in\mathcal{N}$ then we have $\gcd(a,b')=\gcd(a',b)=1$.

\begin{align}
Q R&<x^{2/3},\label{eq:CrudeSize}\\
Q R^2&< M x^{1-2\epsilon}.\label{eq:CrudeSize2}
\end{align}

Let $H:=\frac{Q R^2}{M}\log^5{x}$ and let
\begin{align*}
\mathscr{E}&:=\sum_{\substack{ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q r_2)=1}}\frac{\lambda_{q,r_1}\overline{\lambda_{q,r_2}}}{q r_1 r_2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q}\\ (n_1,n_2qr_1)=1\\(n_2,n_1qr_2)=1\\ |n_1-n_2|\ge N/(\log{x})^C}}\alpha_{n_1}\overline{\alpha_{n_2}}\\
&\qquad\qquad \times\sum_{1\le |h|\le H}\hat{\psi}_0\Bigl(\frac{h M}{q r_1 r_2}\Bigr)e\Bigl(\frac{ah\overline{n_1 r_2}}{q r_1}+\frac{ah\overline{n_2 q r_1}}{r_2}\Bigr).
\end{align*}

\begin{align*}
\mathscr{E}&:=\sum_{\substack{ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q r_2)=1}}\frac{\lambda_{q,r_1}\overline{\lambda_{q,r_2}}}{q r_1 r_2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q}\\ (n_1,n_2qr_1)=1\\(n_2,n_1qr_2)=1\\ |n_1-n_2|\ge N/(\log{x})^C}}\alpha_{n_1}\overline{\alpha_{n_2}}\\
&\qquad\qquad \times\sum_{1\le |h|\le H}\hat{\psi}_0\Bigl(\frac{h M}{q r_1 r_2}\Bigr)e\Bigl(\frac{ah\overline{n_1 r_2}}{q r_1}+\frac{ah\overline{n_2 q r_1}}{r_2}\Bigr).
\end{align*}

\begin{align*}
\frac{ah\overline{n_1 r_2}}{q r_1}&=\frac{-ah\overline{q r_1}}{n_1 r_2}+\frac{ah}{q r_1 r_2 n_1}\Mod{1}.
\end{align*}

\begin{align*}
\mathscr{E}_1&:=\sum_{\substack{ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q r_2)=1}}\frac{\lambda_{q,r_1}\overline{\lambda_{q,r_2}}}{q r_1 r_2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q}\\ (n_1,n_2qr_1)=1\\(n_2,n_1qr_2)=1\\ |n_1-n_2|\ge N/(\log{x})^C}}\alpha_{n_1}\overline{\alpha_{n_2}}\\
&\qquad\qquad\times\sum_{1\le |h|\le H}\hat{\psi}_0\Bigl(\frac{h M}{q r_1 r_2}\Bigr)e\Bigl(\frac{ ah\overline{n_2 q r_1}(n_1-n_2)}{n_1 r_2}\Bigr).
\end{align*}

\begin{align*}
\mathscr{F}&:=\sum_{\substack{ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q r_1)=1}}\frac{\lambda_{q,r_1}\overline{\lambda_{q,r_2}}}{q r_1 r_2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q}\\ (n_1,n_2qr_1)=1\\(n_2,n_1qr_2)=1\\ |n_1-n_2|\ge N/(\log{x})^C}}\alpha_{n_1}\overline{\alpha_{n_2}}\\
&\qquad\qquad\qquad\times\sum_{1\le |h|\le H_2}\hat{\psi}_0\Bigl(\frac{h M}{q r_1 r_2}\Bigr)e\Bigl(\frac{ah\overline{n_1 r_2}}{q r_1}+\frac{ah\overline{n_2 q r_1}}{r_2}\Bigr).
\end{align*}

We first apply Lemma \ref{lmm:Simplification} to $\mathscr{F}$. This shows that
\[
\mathscr{F}\ll \frac{N^2}{Q x^\epsilon}+\exp((\log\log{x})^5)\sup_{\substack{H'\le 2H\\ Q'\le 2Q\\ R_1,R_2\le 2R}}|\mathscr{F}_2|,
\]
with $\mathscr{F}_2$ as given by $\mathscr{E}'$ in Lemma \ref{lmm:Simplification}. We now rewrite the congruence $n_1\equiv n_2\Mod{q}$ by $n_2=n_1+k q$ for some $N/(q\log^{C}{x})\le |k|\le K$ where 
\[
K:=\frac{N}{Q}.
\]
Thus we see that 
\begin{align*}
\mathscr{F}_2&=\sum_{\substack{Q\le q\le Q'\\ (q,a)=1}}\sum_{\substack{R\le r_1\le  R_1\\ R\le r_2\le R_2\\ (r_1,a r_2)=1\\ (r_2,a q r_1)=1}}\frac{\lambda_{q,r_1}\overline{\lambda_{q,r_2}}}{q r_1 r_2}\sum_{\substack{n\sim N\\ (n,qr_1)=1}}\sum_{\substack{N/(q\log^{C}{x})\le |k|\le K\\ n+k q\sim N\\ (n+k q,qr_2n_1)=1\\ (n r_2,n+k q)\in\mathcal{N}}}\alpha_{n}\overline{\alpha_{n+k q}}\\
&\qquad\qquad\times\sum_{1\le |h| \le H'} e\Bigl(\frac{- a h k\overline{(n+k q) r_1}}{n r_2}\Bigr).
\end{align*}
We wish to show $\mathscr{F}_2\ll N^2/Q x^{2\epsilon}$. We apply Cauchy-Schwarz in the $q,r_1,r_2$ variables to eliminate the $\lambda_{q,r}$ coefficients, giving
\[
\mathscr{F}_2\ll \frac{|\mathscr{F}_3|^{1/2}}{Q^{1/2} R},
\]
where
\begin{align*}
\mathscr{F}_3:=\sum_{q\sim Q}\sum_{\substack{r_1,r_2\sim R\\ (r_1,r_2)=1}}\Biggl|\sum_{\substack{n\sim N\\ (n,q r_1)=1}}\sum_{\substack{N/(q\log^{C}{x})\le |k|\le K\\ n+kq\sim N\\ (n+k q,q n r_2)=1\\ (n r_2,n+k q)\in\mathcal{N}}}\sum_{1\le |h| \le H'} c_{n,k,q,h} e\Bigl( \frac{-a h k\overline{(n+kq) r_1}}{ n r_2}\Bigr)\Biggr|^2,
\end{align*}
for some 1-bounded coefficients $c_{n,k,q,h}$. We wish to show $\mathscr{F}_3\ll R^2 N^4 /Q x^{4\epsilon}$. (Here we have extended the summation of $q,r_1,r_2$ slightly for an upper bound.)

We insert smooth majorants for $r_1$ and $r_2$, extend the summation for an upper bound, then expand the square and swap the order of summation. After dropping some summation conditions on the outer variables for an upper bound, this leaves us with
\[
\mathscr{F}_3\le \sum_{n_1,n_2\sim N}\sum_{\substack{|k_1|,|k_2|\le K\\ n_1+k_1q\sim N\\ n_2+k_2q\sim N}}\sum_{1\le |h_1|,|h_2|\le H'}\sum_{\substack{q\sim Q\\ (n_1+k_1q,n_1n_2)=1\\ (n_2+k_2q,n_1n_2)=1}}\Bigl|\sum_{\substack{r_1,r_2\\ (r_1,n_1n_2 r_2)=1\\ (r_2,r_1s)=1}}g(r_1,r_2)e\Bigl(\frac{\ell\overline{s r_1}}{n_1n_2r_2}\Bigr)\Bigr|,
\]
where
\begin{align*}
g(r_1,r_2)&:=\psi_0\Bigl(\frac{r_1}{R}\Bigr)\psi_0\Bigl(\frac{r_2}{R}\Bigr),\\
\ell&:=a (h_1 k_1 n_2(n_2+k_2 q)-h_2 k_2 n_1(n_1+k_1 q)),\\
s&:=(n_1+k_1 q)(n_2+k_2q).
\end{align*}
Here we have crucially made use of the fact that $(n_1r_2,n_1+k_1q),(n_2r_2,n_2+k_2q)\in\mathcal{N}$ and so we may assume $\gcd(n_1,n_2+k_2q)=\gcd(n_2,n_1+k_1q)=1$ to give the conditions in the $q$-summation.

We split our upper bound for $\mathscr{F}_3$ according to whether $\ell=0$ or not:
\[
\mathscr{F}_3\le \mathscr{F}_{\ell=0}+\mathscr{F}_{\ell\ne 0}.
\]
We first consider $\mathscr{F}_{\ell=0}$, the contribution from the `diagonal' terms with $\ell=0$. Since $(n_2,n_2+k_2q)=1$ we have $(k_2,n_2+k_2q)=1$ and so $k_2|h_1k_1n_2$ for these terms. Thus
\begin{align*}
\mathscr{F}_{\ell=0}&\ll \sum_{\substack{q\sim Q\\ r_1,r_2\sim R}}\sum_{\substack{|h_1|\le H\\ |k_1|\le K\\ n_2\sim N}}\sum_{k_2|h_1k_1n_2}\,\,\sum_{h_2n_1|h_1k_1n_2(n_2+k_2q)}1\\
&\ll (\log{x})^{O(1)}Q R^2 H K N\\
&\ll (\log{x})^{O(1)} \frac{Q R^4 N^2 }{M}. 
\end{align*}
This gives $\mathscr{F}_{\ell=0}\ll R^2 N^4/Q x^{4\epsilon}$ provided
\[
M>\frac{x^{6\epsilon} Q^2 R^2}{N^2}.
\]
Recalling $MN\asymp x$, this is satisfied if
\begin{equation}
Q R<x^{1/2-4\epsilon} N^{1/2}.
\label{eq:FouvryCond2}
\end{equation}
We now consider the terms with $\ell\ne 0$. We let $t=n_1n_2$ and put each of $\ell$, $t$, $s$ into one of $O(\log^3{x})$ dyadic ranges. Thus 
\begin{equation}
\mathscr{F}_{\ell\ne 0} \ll (\log{x})^3\sup_{\substack{N^2\ll S,T\ll N^2 \\ L\ll R^2 N^3(\log{x})^2/M}}\sum_{s\sim S}\sum_{t\sim T}\sum_{\ell\sim L}b_{\ell,s,t}\sum_{\substack{r_1,r_2\\ (s r_1,r_2 t)=1}}g(r_1,r_2)e\Bigl(\frac{\ell \overline{s r_1}}{r_2 t}\Bigr),
\label{eq:FouvryOffDiag}
\end{equation}
where $b_{\ell,s,t}$ are complex coefficients satisfying
\[
|b_{\ell,s,t}|\le \mathop{\sum_{q\sim Q}\,\, \sum_{|k_1|,|k_2|\le K}\,\,\sum_{1\le |h_1|,|h_2|\le H'}\,\,\sum_{n_1,n_2\sim N}}\limits_{\substack{\ell=a(h_1k_1n_2(n_2+k_2q)-h_2k_2n_1(n_1+k_1q))\\
s=(n_1+k_1q)(n_2+k_2q)\\ t=n_1n_2}}1.
\]
We can now apply Lemma \ref{lmm:DeshouillersIwaniec} to bound the sum \eqref{eq:FouvryOffDiag}. This gives
\begin{align*}
\mathscr{F}_{\ell\ne 0}& \ll x^\epsilon\Bigl(RT(ST+L)(R+RS)+R^3T\sqrt{(ST+L)S}+R^2LS\Bigr)^{1/2}\|b\|_2\\
&\ll x^{2\epsilon}\Biggl(R N^2\Bigl(N^4+\frac{N^3 R^2}{M}\Bigr)(R+R N^2)\\
&\qquad\qquad\qquad+R^3N^2\sqrt{\Bigl(N^4+\frac{N^3 R^2}{M}\Bigr)N^2}+R^2\frac{N^3 R^2}{M}N^2\Biggr)^{1/2}\|b\|_2.
\end{align*}
Since $MN\asymp x$, this simplifies to
\begin{align}
\mathscr{F}_{\ell\ne0}&\ll x^{2\epsilon} \Bigl(R^2 N^8+\frac{R^4 N^8}{x}+R^3N^5+\frac{R^4 N^5}{x^{1/2}}\Bigr)^{1/2}\|b\|_2.\label{eq:FouvryFOffDiag}
\end{align}
We first consider $\|b\|_2$. We see that
\[
\|b\|_2^2\le \sum_{\ell\sim L}\sum_{s\sim S}\sum_{\substack{t\sim T\\ (s,t)=1}}\Bigl(\sum_{\substack{n_1n_2=t\\ n_1,n_2\sim N}}\sum_{\substack{|k_1|,|k_2|\le K\\ q\sim Q \\ s=(n_1+k_1q)(n_2+k_2q)}}\#\mathcal{C}\Bigr)^2,
\]
where $\mathcal{C}=\mathcal{C}(k_1,k_2,q,n_1,n_2,\ell)$ is the set
\begin{align*}
\mathcal{C}=\{(h_1,h_2)\in [1,H]^2:&\,\ell=a(h_1k_1n_2(n_2+k_2q)-h_2k_2n_1(n_1+k_1q))\}.
\end{align*}
There are at most $\tau(t)=x^{o(1)}$ choices of $n_1,n_2$ given $t$. There are at most $\tau(s)=x^{o(1)}$ choices of $n_1+k_1q$ and $n_1+k_2q$ given $s$. There are then at most $\tau(s-n_1)\tau(s-n_2)=x^{o(1)}$ choices of $k_1,k_2,q$ given $n_1+k_1q$ and $n_2+k_2q$ and $n_1,n_2$. Thus there are at most $x^{o(1)}$ choices of $n_1,n_2,k_1,k_2,q$ given $s$ and $t$. Moreover, since $(s,t)=1$ we have $(n_1,k_1)=(n_2,k_2)=1$. Thus, by Cauchy-Schwarz, we see that
\begin{align*}
\|b\|_2^2&\ll x^{o(1)}\sum_{\ell\sim L}\sum_{s\sim S}\sum_{\substack{t\sim T\\ (s,t)=1}}\sum_{\substack{n_1n_2=t\\ n_1,n_2\sim  N}}\sum_{q\sim Q}\sum_{\substack{|k_1|,|k_2|\le K\\ s=(n_1+k_1q)(n_2+k-2q)}}\#\mathcal{C}^2\\
&\ll x^{o(1)} \mathop{\sum_{n_1,n_2,k_1,k_2,q}\,\,\sum_{h_1,h_2,h_3,h_4}}\limits_{\substack{(h_1-h_3)k_1n_2(n_2+k_2q)=(h_2-h_4)k_2n_1(n_1+k_1q)\\ (n_1,k_1)=(n_2,k_2)=1}}1.
\end{align*}
Here we have suppressed the ranges for the variables in the final line for convenience. We see that if $h_1-h_3=0$, then we must have $h_2-h_4=0$, and so the total contribution from terms with $h_1-h_3=0$ is
\begin{align}
&\ll x^{o(1)} H^2 N^2 K^2Q\ll x^{o(1)} \frac{Q^2 R^4}{M^2}N^2\frac{N^2}{Q^2}Q\ll x^{o(1)} \frac{Q R^4N^6}{x^2}.
\label{eq:bDiag}
\end{align}
If instead $h_1-h_3\ne 0$, then we first fix a choice of $h_1$, $h_3$, $n_2$, $k_2$ and $q$, for which there are $O(H^2 N K Q)$ choices. Since $(k_1,n_1)=1$, we have that $n_1(n_1+k_1q)|(h_1-h_3)n_2(n_2+k_2q)$, so there are $O(x^{o(1)})$ choices of $n_1,k_1$. Given such a choice of $n_1,k_1$, we see that $(h_2-h_4)$ is uniquely determined, and so there are $O(H)$ choices of $h_2$ and $h_4$. Thus the total contribution from terms with $h_1-h_3\ne 0$ is 
\begin{equation}
\ll x^{o(1)}H^3 N K Q\ll x^{o(1)} \frac{Q R^4N^6}{x^2}\Bigl(\frac{Q^2R^2}{x N}\Bigr).
\label{eq:bOffDiag}
\end{equation}
But we have $Q^2 R^2<x^{1-8\epsilon}N$ by \eqref{eq:FouvryCond2}, so we find that the bound \eqref{eq:bDiag} is larger than the bound \eqref{eq:bOffDiag}. Thus
\begin{equation}
\|b\|_2^2\ll x^{\epsilon}\frac{Q R^4 N^6}{x^2}.\label{eq:bBound}
\end{equation}
Putting together \eqref{eq:bBound} and \eqref{eq:FouvryFOffDiag}, we find that
\begin{align*}
\mathscr{F}_{\ell\ne 0}&\ll x^{3\epsilon}\Bigl(R^2 N^8+\frac{R^4 N^8}{x}+R^3 N^5+\frac{R^4 N^5}{x^{1/2}}\Bigr)^{1/2}\Bigl(\frac{Q R^4 N^6}{x^2}\Bigr)^{1/2}\\
&\ll x^{3\epsilon}\Bigl(\frac{Q^{1/2} R^3 N^7}{x}+\frac{Q^{1/2} R^4 N^7}{x^{3/2}}+\frac{Q^{1/2}R^{7/2}N^{11/2}}{x}+\frac{Q^{1/2}R^4 N^{11/2}}{x^{5/4}}\Bigr).
\end{align*}
Thus we have $\mathscr{F}_{\ell\ne 0}\ll R^2 N^4/(Q x^{4\epsilon})$ provided we have
\begin{align}
N^6 R^2 Q^{3}&<x^{2-14\epsilon},\\
N^6 R^4 Q^{3}&<x^{3-14\epsilon},\\
N^{3}R^{3}Q^{3}&<x^{2-14\epsilon},\\
N^{3}R^{4}Q^{3}&<x^{5/2-14\epsilon}.
\end{align}
This gives the result.

\begin{align*}
