\begin{align*}
\mathscr{D}&:=\sum_{\substack{ (d,a)=1}}\psi_0\Bigl(\frac{d}{D}\Bigr)\sum_{\substack{q_1,q_2\sim Q \\ (q_1,aq_2)=1\\ (q_2,a d q_1)=1}}\sum_{\substack{r_1,r_2\sim R\\ (r_1,aq_2 r_2)=1\\ (r_2,a d q_1 r_1)=1}}\frac{\eta_{d,q_1,r_1}\overline{\eta_{d,q_2,r_2}}}{d q_1 q_2 r_1 r_2}\\
