\]
We first apply Lemma \ref{lmm:KRough} with the trivial factorization $Q_1=Q R$, $Q_2=1$. This gives the result provided
\begin{equation}
\frac{M Q^{5/2} R^{5/2} }{x^{1-15\epsilon}}<N_3<\frac{x^{2-15\epsilon} }{Q^3 R^3 M}.\label{eq:N3Range1}
\end{equation}
We now apply Lemma \ref{lmm:KRough} with the factorization $Q_1=Q$, $Q_2=R$, which gives the result provided
\begin{equation}
\frac{M Q^{5/2}R^{3}}{x^{1-15\epsilon}}<N_3<\frac{x^{2-15\epsilon}}{Q^3 R^2 M}.\label{eq:N3Range2}
\end{equation}
We see that if $Q,R$ satisfy $Q^7 R^9<x^4$ and $M<x^{1-20\epsilon}/(QR)^{15/8}$ then
\begin{align*}
\frac{M Q^{5/2} R^3}{x^{1-15\epsilon}}&=\frac{x^{2-15\epsilon} }{M Q^3 R^3}\Bigl(\frac{M^2 Q^{11/2} R^6}{x^{3-30\epsilon}}\Bigr)\\
&<\frac{x^{2-15\epsilon}}{M Q^3 R^3}\Bigl(\frac{Q^{7/4}R^{9/4}}{x^{1+10\epsilon}}\Bigr)\\
&<\frac{x^{2-15\epsilon} }{M Q^3 R^3}.
\end{align*}
Thus the ranges \eqref{eq:N3Range1} and \eqref{eq:N3Range2} overlap, giving the result for the range
\[
\frac{M Q^{5/2}R^{5/2}}{x^{1-15\epsilon}}<N_3<\frac{x^{2-15\epsilon} }{Q^3 R^2 M}.
\]
Since $M<x^{1-20\epsilon} Q^{-15/8}R^{-15/8}$, we see that 
