\frac{M Q^{5/2} R^{5/2}}{x^{1-15\epsilon}}<\frac{x^{1/3-\epsilon}}{M^{1/3}}.\label{eq:N3Lower}
\end{equation}
Since $M<x^{1-20\epsilon} Q^{-15/8}R^{-15/8}$ and $Q^9 R<x^{32/7}$, we have
\begin{equation}
\frac{x^{2-15\epsilon}}{M Q^3 R^2}>\frac{x^{1+\epsilon} }{Q^{9/8}R^{1/8}}>x^{3/7+\epsilon}.\label{eq:N3Upper}
\end{equation}
Therefore, using \eqref{eq:N3Lower} and \eqref{eq:N3Upper}, we see that \eqref{eq:N3Range1} and \eqref{eq:N3Range2} cover the range
\[
\frac{x^{1/3-\epsilon }}{M^{1/3}}\le N_3\le x^{3/7+\epsilon}.
\]
This gives the result.

